entries[32837] = { ["name"] = "Kriegsgleve von Azzinoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n302 - 562 Schaden Tempo 2.80\n(154.29 Schaden pro Sekunde)\n+22 Beweglichkeit\n+47 Ausdauer\nErhöht Eure Trefferwertung um + 21.\nHaltbarkeit 130 / 130\nKlassen: Krieger , Schurke , Todesritter , Mönch\nBenötigt Stufe 70\n\nDie Zwillingsklingen von Azzinoth (0/2)\nKriegsgleve von Azzinoth\nKriegsgleve von Azzinoth\n(2) Set : Eure Nahkampfangriffe gewähren eine Chance, 10 Sek. lang Euer Tempo um 450 zu erhöhen. (45s Abklingzeit)\n(2) Set : Erhöht Angriffskraft im Kampf gegen Dämonen um 200.\nVerkaufspreis:" }
entries[32838] = { ["name"] = "Kriegsgleve von Azzinoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schwert\n194 - 361 Schaden Tempo 1.80\n(154.17 Schaden pro Sekunde)\n+21 Beweglichkeit\n+46 Ausdauer\nErhöht Eure kritische Trefferwertung um + 23.\nHaltbarkeit 130 / 130\nKlassen: Krieger , Schurke , Todesritter , Mönch\nBenötigt Stufe 70\n\nDie Zwillingsklingen von Azzinoth (0/2)\nKriegsgleve von Azzinoth\nKriegsgleve von Azzinoth\n(2) Set : Eure Nahkampfangriffe gewähren eine Chance, 10 Sek. lang Euer Tempo um 450 zu erhöhen. (45s Abklingzeit)\n(2) Set : Erhöht Angriffskraft im Kampf gegen Dämonen um 200.\nVerkaufspreis:" }
